1	import * as React from "react";
2	
3	export interface ContainerProps extends React.HTMLAttributes<HTMLElement> {
4	  as?: React.ElementType;
5	}
6	
7	/**
8	 * The app's main section width. Desktop-first: spans 85% of the viewport,
9	 * centred, capped at --container-app (1500px) so text lines stay readable for
10	 * the low-vision audience on very large monitors. Used by the header, the page
11	 * <main>, and the footer so they all align to the same column.
12	 */
13	export function Container({
14	  as: Tag = "div",
15	  className = "",
16	  children,
17	  ...rest
18	}: ContainerProps) {
19	  return (
20	    <Tag
21	      className={["mx-auto w-[85%] max-w-app", className]
22	        .filter(Boolean)
23	        .join(" ")}
24	      {...rest}
25	    >
26	      {children}
27	    </Tag>
28	  );
29	}
